import requests

def check_url(url):
    try:
        resp = requests.get(url, timeout=5)
        code = resp.status_code
        if code == 200:
            msg = 'OK'
        elif code == 404:
            msg = 'Not Found'
        elif code == 403:
            msg = 'Forbidden'
        else:
            msg = str(code)
        print(f"Status: {code} {msg}")
    except requests.exceptions.RequestException as e:
        print(f"Request failed: {e}")

check_url('https://httpbin.org/status/200')
check_url('https://httpbin.org/status/404')
